export function planDeparture(windows: LockWindow[], ready: number, cruise: number): Departure | null {
    const entry = nextEntry(windows, ready + cruise);
    // No entry left today: nextEntry gave no usable time (not a number, earlier than the arrival, or past the end of the day).
    if (!Number.isFinite(entry) || entry < ready + cruise || entry >= DAY) return null;
